64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
71	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
72	     * and a dotted domain (e.g. {@code not-an-email}).
73	     */
74	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
75	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
76	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
77	
78	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
79	    private static final String DEFAULT_COUNTRY_CODE = "61";
80	
81	    /** Maximum number of owners a single city may contain; a create is rejected once it is reached. */
82	    private static final int MAX_OWNERS_PER_CITY = 50;
83	
84	    /** Maximum number of owners that may be registered on a single day; a create is rejected once it is reached. */
85	    private static final int MAX_OWNERS_PER_DAY = 100;
86	
87	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
88	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
89	
90	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
91	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
92	
93	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
94	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
95	        "ST", "STREET",
96	        "RD", "ROAD",
97	        "AVE", "AVENUE");
98	
