142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        List<String> missingFields = new ArrayList<>();
146	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
147	            missingFields.add("firstName");
148	        }
149	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
150	            missingFields.add("lastName");
151	        }
152	        // Normalize the address up front; the required-field check rejects it when it is blank
153	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
154	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
155	        if (!StringUtils.hasText(normalizedAddress)) {
156	            missingFields.add("address");
157	        }
158	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
159	            missingFields.add("city");
160	        }
161	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
162	            missingFields.add("telephone");
163	        }
164	        if (!missingFields.isEmpty()) {
165	            throw new InvalidRequestException(missingFields);
166	        }
167	        HttpHeaders headers = new HttpHeaders();
168	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
169	        // Store (and later return) the normalized address computed above.
170	        owner.setAddress(normalizedAddress);
171	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
172	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
173	        owner.setTelephone(normalizedTelephone);
174	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
175	        owner.setEmail(normalizeEmail(owner.getEmail()));
176	        // Default the (optional) registration date to the server's current date when none was supplied.
177	        if (owner.getRegistrationDate() == null) {
178	            owner.setRegistrationDate(LocalDate.now());
179	        }
180	        // Reject the request once the maximum number of owners for the owner's registration day has
181	        // been reached (100 or more owners already created on that date).
182	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
183	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
184	        }
185	        // Reject the request when the owner's city has already reached its owner capacity.
186	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
187	            throw new CityCapacityException(owner.getCity());
188	        }
189	        // Reject the request if the E.164 telephone is already used by another owner.
190	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
191	            throw new DuplicateTelephoneException(normalizedTelephone);
192	        }
193	        // Reject the request if another owner already shares the same last name and address
194	        // (compared case-insensitively with collapsed whitespace), unless the caller opts in
195	        // by setting 'sharesHousehold' true. When they do opt in and an existing household is
196	        // matched, assign a stable shared 'householdId' to the new owner and backfill it onto
197	        // every existing member that does not yet carry it.
198	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
199	        if (!householdMembers.isEmpty()) {
200	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
201	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
202	            }
203	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
204	            owner.setHouseholdId(householdId);
205	            for (Owner member : householdMembers) {
206	                if (!householdId.equals(member.getHouseholdId())) {
207	                    member.setHouseholdId(householdId);
208	                    this.clinicService.saveOwner(member);
209	                }
210	            }
211	        }
212	        // Record how many existing owners already share this first name and last name
213	        // (compared case-insensitively) before this owner is created.
214	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
215	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' before persisting.
216	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
217	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
218	        // digits of the registration date year (e.g. 'SYD-SMI-0007-M26').
219	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
220	        this.clinicService.saveOwner(owner);
221	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
222	        headers.setLocation(UriComponentsBuilder.newInstance()
223	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
224	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
225	    }
