244	    /**
245	     * Generate a customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3} is the
246	     * upper-cased first three letters of {@code city}, {@code LAST3} is the upper-cased first three
247	     * letters of {@code lastName} and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to
248	     * one more than the current number of owners already in that city (e.g. {@code SYD-SMI-0007}).
249	     *
250	     * @param city     the owner's city
251	     * @param lastName the owner's last name
252	     * @return the generated customer code
253	     */
254	    private String generateCustomerCode(String city, String lastName) {
255	        String cityPrefix = city.length() >= 3 ? city.substring(0, 3) : city;
256	        String lastPrefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
257	        String normalizedCity = normalizeForComparison(city);
258	        int sequence = (int) this.clinicService.findAllOwners().stream()
259	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
260	            .count() + 1;
261	        return String.format("%s-%s-%04d", cityPrefix.toUpperCase(Locale.ROOT),
262	            lastPrefix.toUpperCase(Locale.ROOT), sequence);
263	    }
264	
265	    /**
266	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
267	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
268	     *
269	     * @param customerCode     the owner's already-assigned customer code
270	     * @param registrationDate the owner's registration date
271	     * @return the generated membership number
272	     */
273	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
274	        String yy = String.format("%02d", registrationDate.getYear() % 100);
275	        return String.format("%s-M%s", customerCode, yy);
276	    }
277	
278	    /**
279	     * Count the existing owners that share the given first name and last name, comparing each
280	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
281	     * yet persisted, so it is not included in the count.
282	     *
283	     * @param firstName the incoming owner's first name
284	     * @param lastName  the incoming owner's last name
285	     * @return the number of existing namesakes
286	     */
287	    private int countNamesakes(String firstName, String lastName) {
288	        String normalizedFirstName = normalizeForComparison(firstName);
289	        String normalizedLastName = normalizeForComparison(lastName);
290	        return (int) this.clinicService.findAllOwners().stream()
291	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
292	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
293	            .count();
294	    }
295	
296	    /**
297	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
298	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
299	     *
300	     * @param city the incoming owner's city
301	     * @return the number of existing owners already in that city
302	     */
303	    private int countOwnersInCity(String city) {
304	        String normalizedCity = normalizeForComparison(city);
305	        return (int) this.clinicService.findAllOwners().stream()
306	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
307	            .count();
308	    }
309	
310	    /**
311	     * Count the existing owners whose registration date equals the given date. The incoming owner is
312	     * not yet persisted, so it is not included in the count.
313	     *
314	     * @param registrationDate the incoming owner's registration date
315	     * @return the number of existing owners already registered on that date
316	     */
317	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
318	        return (int) this.clinicService.findAllOwners().stream()
319	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
320	            .count();
321	    }
322	
323	    /**
324	     * Find the existing owners that live in the same household as the given values, i.e. those that
325	     * share both the last name and the address when each is compared case-insensitively with
326	     * collapsed whitespace.
327	     *
328	     * @param lastName the incoming owner's last name
329	     * @param address  the incoming owner's address
330	     * @return the matching existing owners (possibly empty)
331	     */
332	    private List<Owner> findHouseholdMembers(String lastName, String address) {
333	        String normalizedLastName = normalizeForComparison(lastName);
334	        String normalizedAddress = normalizeForComparison(address);
335	        return this.clinicService.findAllOwners().stream()
336	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
337	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
338	            .toList();
339	    }
340	
341	    /**
342	     * Generate a stable shared household identifier for the given last name and address. The value is
343	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
344	     * and address, so every owner joining the same household resolves to the same identifier. It is the
345	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
346	     *
347	     * @param lastName the household's last name
348	     * @param address  the household's address
349	     * @return the stable household identifier
350	     */
351	    private String generateHouseholdId(String lastName, String address) {
352	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
353	        try {
354	            byte[] digest = MessageDigest.getInstance("SHA-256")
355	                .digest(key.getBytes(StandardCharsets.UTF_8));
356	            StringBuilder sb = new StringBuilder(digest.length * 2);
357	            for (byte b : digest) {
358	                sb.append(String.format("%02x", b));
359	            }
360	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
361	        } catch (java.security.NoSuchAlgorithmException e) {
362	            throw new IllegalStateException("SHA-256 not available", e);
363	        }
364	    }
365	
366	    /**
367	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
368	     * single space, upper-case the result and expand common street-type abbreviations token by token
369	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
370	     * to the empty string. The result is the canonical form that is stored, returned and used for every
371	     * address comparison (household duplicate detection and the shared household id).
372	     *
373	     * @param address the raw address, may be {@code null}
374	     * @return the normalized address
375	     */
376	    private String normalizeAddress(String address) {
377	        if (address == null) {
378	            return "";
379	        }
380	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
381	        if (collapsed.isEmpty()) {
382	            return "";
383	        }
384	        String[] tokens = collapsed.split(" ");
385	        StringBuilder sb = new StringBuilder(collapsed.length());
386	        for (int i = 0; i < tokens.length; i++) {
387	            if (i > 0) {
388	                sb.append(' ');
389	            }
390	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
391	        }
392	        return sb.toString();
393	    }
394	
395	    /**
396	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
397	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
398	     *
399	     * @param value the raw value, may be {@code null}
400	     * @return the normalized value
401	     */
402	    private String normalizeForComparison(String value) {
403	        if (value == null) {
404	            return "";
405	        }
406	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
407	    }
408	
409	    /**
410	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
411	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
412	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
413	     * is returned lower-cased.
414	     *
415	     * @param email the raw email from the request payload, may be {@code null}
416	     * @return the lower-cased email, or {@code null} when none was provided
417	     */
418	    private String normalizeEmail(String email) {
419	        if (!StringUtils.hasText(email)) {
420	            return null;
421	        }
422	        if (!EMAIL_PATTERN.matcher(email).matches()) {
423	            throw new InvalidRequestException(List.of("email"));
424	        }
425	        return email.toLowerCase(Locale.ROOT);
426	    }
427	
428	    /**
429	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
430	     * already carries a leading '+' keeps its country code; otherwise the default country code
431	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
432	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
433	     * is thrown (mapped to 400 Bad Request).
434	     *
435	     * @param telephone the raw telephone from the request payload
436	     * @return the E.164 string (e.g. {@code +61412345678})
437	     */
438	    private String normalizeTelephone(String telephone) {
439	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
440	        String candidate;
441	        if (cleaned.startsWith("+")) {
442	            candidate = cleaned;
443	        } else {
444	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
445	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
446	        }
447	        if (!E164_PATTERN.matcher(candidate).matches()) {
448	            throw new InvalidRequestException(List.of("telephone"));
449	        }
450	        return candidate;
451	    }
