465	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
466	    @Override
467	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
468	        Owner owner = this.clinicService.findOwnerById(ownerId);
469	        if (owner == null) {
470	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
471	        }
472	        HttpHeaders headers = new HttpHeaders();
473	        Pet pet = petMapper.toPet(petFieldsDto);
474	        owner.setId(ownerId);
475	        pet.setOwner(owner);
476	        pet.getType().setName(null);
477	        this.clinicService.savePet(pet);
478	        PetDto petDto = petMapper.toPetDto(pet);
479	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
480	            .buildAndExpand(pet.getId()).toUri());
481	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
482	    }
